const raw = $('RackWatch Alert').item.json.body || $('RackWatch Alert').item.json;
const snap = $json;
const alert = {
  title: String(raw.title || 'RackWatch alerta'),
  message: String(raw.message || ''),
  severity: String(raw.severity || 'warning'),
  source: String(raw.source || 'rackwatch'),
  host: String(raw.host || snap.instance || ''),
  service: String(raw.service || ''),
  fingerprint: String(raw.fingerprint || '')
};
return [{ json: { alert, service: alert.service || 'rackwatch', snapshot: snap } }];

const a = $('Preparar alerta').item.json.alert;
const content = String($json.message?.content || $json.error || 'Ollama no devolvió diagnóstico.');
const esc = (s) => s.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
const header = `<b>RackWatch · ${esc(a.severity.toUpperCase())}</b>
<b>${esc(a.title)}</b>
Servicio: <code>${esc(a.service || 'host')}</code>
Fingerprint: <code>${esc(a.fingerprint || 'n/a')}</code>

`;
return [{ json: { text: (header + esc(content)).slice(0, 3950), fingerprint: a.fingerprint } }];

const m = $json.message || $json.edited_message || {};
const text = String(m.text || '').trim();
return [{ json: { chatId: m.chat?.id, user: m.from?.username || m.from?.first_name || 'usuario', text: text || 'Diagnostica el estado actual del homelab.' } }];

